      "numero": 66,
      "ar": "قَدْ كَانَتْ ءَايَٰتِي تُتْلَىٰ عَلَيْكُمْ فَكُنتُمْ عَلَىٰ أَعْقَٰبِكُمْ تَنكِصُونَ",
